import { vsDiff, type DiffResult } from './shader-diff';

/** Run the actual C translator's output against its CPU interpreter, with
 * different bone matrices. Fixtures are generated by tools/check.sh. */
export async function runShaderContracts() {
  const adapter=await navigator.gpu?.requestAdapter();
  if (!adapter) throw Error('WebGPU adapter unavailable');
  const device=await adapter.requestDevice(), failures:string[]=[];
  device.addEventListener('uncapturederror',e=>failures.push(e.error.message));
  const result:DiffResult={modules:0,vertices:0,components:0,bad:0,maxRel:0,worst:''};
  try {
    for (let op=20;op<=24;op++) {
      const name=`vs_${op}`, responses=await Promise.all([
        fetch(`/shader-tests/${name}.wgsl`,{cache:'no-store'}),fetch(`/shader-tests/${name}.vec`,{cache:'no-store'})]);
      if (responses.some(r=>!r.ok)) throw Error('Run tools/check.sh and rebuild the web page to generate shader fixtures');
      await vsDiff(device,name,await responses[0].text(),await responses[1].arrayBuffer(),result,failures);
    }
    await device.queue.onSubmittedWorkDone();
    return {passed:result.modules===5 && result.bad===0 && !failures.length,result,failures};
  } finally { device.destroy(); }
}
